INSERT IGNORE INTO `films` (`id`, `average_rating`, `country`, `description`, `duration_minutes`, `episode_count`, `follow_count`, `last_update`, `rating_count`, `release_date`, `season`, `series`, `status`, `thumbnail_url`, `title`, `trailer_url`, `thumbnail_file_id`) VALUES ('f1111111-1111-1111-1111-111111111111',4.5,'USA','Nội dung phim dựa trên bộ sách của Robert Jordan, lấy bối cảnh một thế giới giả tưởng cao cấp, nơi có phép thuật, nhưng chỉ một số người mới có thể tiếp cận nó, một người phụ nữ tên là Moiraine băng qua đường với 5 nam nữ thanh niên. Điều này gây ra một cuộc hành trình nguy hiểm, trải dài khắp thế giới.',118,3,341,'2026-08-07 07:28:13.536775',130,'2026-06-12 00:00:00.000000',1,_binary '\0','COMPLETED',NULL,'Vòng Xoay Thời Gian','https://youtu.be/11ZozKfRqvA?si=sNw4afctU6ExD-GF','movie-platform/959a9089-d821-4518-9d73-ba5d11fbbedb.jpg');
INSERT IGNORE INTO `films` (`id`, `average_rating`, `country`, `description`, `duration_minutes`, `episode_count`, `follow_count`, `last_update`, `rating_count`, `release_date`, `season`, `series`, `status`, `thumbnail_url`, `title`, `trailer_url`, `thumbnail_file_id`) VALUES ('f2222222-2222-2222-2222-222222222222',4.2,'VIETNAM','Cau chuyen tinh yeu nhe nhang giua hai nguoi tre lon len o mot thi tran ven bien vao mua he cuoi cung truoc khi buoc vao doi.',105,1,190,'2026-08-07 07:32:41.780552',76,'2026-05-20 00:00:00.000000',1,_binary '\0','COMPLETED',NULL,'Chuyện Tình Mùa Hạ','https://www.youtube.com/watch?v=FcreeUrNFKE','movie-platform/3c852cfa-6620-4c03-8117-f13e4b32cf3f.webp');
INSERT IGNORE INTO `films` (`id`, `average_rating`, `country`, `description`, `duration_minutes`, `episode_count`, `follow_count`, `last_update`, `rating_count`, `release_date`, `season`, `series`, `status`, `thumbnail_url`, `title`, `trailer_url`, `thumbnail_file_id`) VALUES ('f3333333-3333-3333-3333-333333333333',4.7,'KOREA','Mất đi cháu trai trong vụ tai nạn máy bay, diễn viên đóng thế Cha Dal Geon quyết tâm tìm hiểu nguyên nhân vụ việc với sự giúp đỡ của mật vụ Go Hae Ri.',60,16,512,'2026-08-07 10:31:01.248500',214,'2026-04-10 00:00:00.000000',1,_binary '\0','ONGOING',NULL,'Vagabond','https://www.youtube.com/watch?v=tyhnEHCUtv4','movie-platform/2c653a28-8bdb-4922-8309-619973a7bb69.webp');
INSERT IGNORE INTO `films` (`id`, `average_rating`, `country`, `description`, `duration_minutes`, `episode_count`, `follow_count`, `last_update`, `rating_count`, `release_date`, `season`, `series`, `status`, `thumbnail_url`, `title`, `trailer_url`, `thumbnail_file_id`) VALUES ('f4444444-4444-4444-4444-444444444444',0,'JAPAN','Sau khi giải quyết xong cuộc khủng hoảng ở Thương Nam, Lâm Thất Dạ đã hoàn thành kỳ huấn luyện và sát hạch Người Gác Đêm kéo dài một năm tại núi Tân Nam. Sau khi chính thức trở thành một Người Gác Đêm, cậu quay trở lại đội 136, cùng các đồng đội bắt đầu một cuộc đối đầu hoàn toàn mới với Giáo hội Cổ Thần… Một Tà thần phương Tây mới lộ diện, những cường giả đỉnh cao của nhân loại tề tựu về Thương Nam, một cơn bão thảm họa khổng lồ đang âm thầm nhen nhóm.',20,0,0,'2026-08-07 07:52:21.232064',0,'2026-12-25 00:00:00.000000',2,_binary '','ONGOING',NULL,' Trảm Thần: Phàm Trần Thần Vực Phần 2','https://www.youtube.com/watch?v=JCXujYvZ2Sw','movie-platform/61cb3a4a-d95a-4433-8927-b8aad5c587d4.webp');
INSERT IGNORE INTO `films` (`id`, `average_rating`, `country`, `description`, `duration_minutes`, `episode_count`, `follow_count`, `last_update`, `rating_count`, `release_date`, `season`, `series`, `status`, `thumbnail_url`, `title`, `trailer_url`, `thumbnail_file_id`) VALUES ('fa010000-0000-0000-0000-000000000001',4.6,'CHINA','Vương Lâm từ nhỏ vốn có tư chất tu luyện kém cỏi. Trong kỳ thi nhập môn của Hằng Nhạc Phái, hắn thất bại, trở thành trò cười của họ hàng. Không cam chịu số phận, và để gia đình không phải xấu hổ thêm, Vương Lâm quyết định một mình rời nhà tìm đến sơn môn Hằng Nhạc Phái. Trên đường đi, hắn gặp một con hổ dữ trên vách núi, buộc phải nhảy xuống vực. Trong lúc rơi, hắn bị hút vào một hang động kỳ bí. Để tránh chết đói, hắn ăn những xác chim thú trong hang và tình cờ tìm thấy Thiên Nghịch Châu trong bụng một con chim trắng đã chết. Sau đó, Vương Lâm được đệ tử Hằng Nhạc Phái tìm thấy. Họ nhầm tưởng hắn vì thất bại mà tự tử, lại chế nhạo thêm lần nữa. Nhờ sự giúp đỡ của Tứ thúc, Vương Lâm được đưa vào Hằng Nhạc Phái qua con đường cửa sau. Tuy nhiên, với tốc độ tu luyện chậm chạp, hắn tiếp tục bị chèn ép và xa lánh. Trong một lần gặp Trương Hổ, hắn biết Trương Hổ đã giết Lưu sư huynh và trốn khỏi phái. Sau đó, Vương Lâm giết chết Tôn Đại Trụ, kẻ định moi móc bí mật Thiên Nghịch Châu. Không lâu sau, Huyền Đạo Tông lấy lý do luận đạo để thôn tính Hằng Nhạc Phái. Vương Lâm rời phái, chuyên tâm tu luyện, đạt đến cảnh giới Ngưng Khí Đại Viên Mãn. Hắn tái ngộ Trương Hổ, giết chết đệ tử của Lão Nhân Tức Mặc, và bị Phù Lệ truy sát. Sau khi tiêu diệt Phù Lệ, Vương Lâm thực hiện đoạt cơ, bước vào cảnh giới Trúc Cơ. Hắn dốc lòng tu luyện Hoàng Tuyền Thăng Khiếu Quyết, nhưng lại bị cuốn vào tranh đấu với Ngô Vũ, kẻ phản bội phái Thi Hồn. Trong khi đó, Đằng Hóa Nguyên tìm đến quê nhà của Vương Lâm, tiêu diệt toàn bộ gia tộc của hắn. Vương Lâm chuyển hóa linh lực trong cơ thể đến cực hạn, chiến đấu với Đằng Hóa Nguyên tại Quyết Minh Cốc. Dù giành thắng lợi, hắn mất đi thân xác, chỉ còn lại thần thức. Tư Đồ Nam cứu lấy thần thức của Vương Lâm, đưa hắn vào Thiên Nghịch Châu để tránh bị tiêu tan, rồi đưa đến chiến trường Vực Ngoại. Vương Lâm mượn Thiên Nghịch Châu, hóa thân thành Thôn Hồn, chiếm lấy thân xác Mã Lương và tiến đến Hỏa Phần Quốc. Tại đây, hắn sử dụng Thiên Nghịch Châu để tiêu diệt vua của Hỏa Linh Thú, khiến toàn bộ đàn Hỏa Linh Thú nổi loạn. Hỏa Phần Quốc khởi động đại trận phong tỏa, người dân tháo chạy sang Tuyên Vũ Quốc để lánh nạn. Cuối cùng, Hỏa Linh Thú phá vỡ trận pháp phong tỏa, Vương Lâm trên đường chạy đến Tu Ma Hải đã cứu được Lý Mộ Uyển đang bị truy sát.',20,30,3100,'2026-08-07 07:25:16.476242',1100,'2025-05-10 00:00:00.000000',1,_binary '','ONGOING',NULL,'Tiên Nghịch','https://www.youtube.com/watch?v=RLNi4b_K2Yc','movie-platform/5f70ff3c-852c-4c31-94bc-9c14a8cadef4.webp');
INSERT IGNORE INTO `films` (`id`, `average_rating`, `country`, `description`, `duration_minutes`, `episode_count`, `follow_count`, `last_update`, `rating_count`, `release_date`, `season`, `series`, `status`, `thumbnail_url`, `title`, `trailer_url`, `thumbnail_file_id`) VALUES ('fa020000-0000-0000-0000-000000000002',4.6,'CHINA','Trong Đại Khư Tàn Lão Thôn, nơi cư ngụ của chín vị lão nhân bí ẩn, có một thiếu niên tên Tần Mục do họ nuôi dưỡng từ nhỏ. Một ngày nọ, con bò mẹ mà Tần Mục chăn dắt bỗng cất tiếng nói tiếng người, từ đó cậu càng nhận ra sự nguy hiểm và huyền bí của vùng đất Đại Khư – nơi bị thần linh bỏ rơi. Ở đây, ma thần xuất hiện trong bóng tối, xương cốt của thần linh múa may trên những tàn tích, xương rồng bảo vệ con, và những con thuyền khổng lồ kéo mặt trời di chuyển… Dù đối diện với bao hiểm nguy, Tần Mục vẫn không hề nao núng, lĩnh hội và dung hòa tất cả những gì chín vị lão truyền dạy, lấy thân bá thể mà khai phá một vùng trời riêng.',20,25,2400,'2026-08-07 07:25:27.578591',920,'2025-07-01 00:00:00.000000',1,_binary '','ONGOING',NULL,'Mục Thần Ký','https://www.youtube.com/watch?v=RLNi4b_K2Yc','movie-platform/3f40bac8-1780-4b89-88cb-f7589152e2e0.webp');
INSERT IGNORE INTO `films` (`id`, `average_rating`, `country`, `description`, `duration_minutes`, `episode_count`, `follow_count`, `last_update`, `rating_count`, `release_date`, `season`, `series`, `status`, `thumbnail_url`, `title`, `trailer_url`, `thumbnail_file_id`) VALUES ('fa030000-0000-0000-0000-000000000003',4.7,'CHINA','Trời đất là quán trọ của muôn vật và chúng sinh, thời gian là kẻ qua đường của xưa và nay.\nGương mặt tàn khuyết mở ra con mắt quỷ dị, nơi ánh nhìn chiếu tới thì sinh linh lầm than, biến thành vùng cấm vĩnh hằng.\nDưới tận thế tàn khốc ấy, con người chẳng khác gì cỏ rơm. Thiếu niên Hứa Thanh vì sinh tồn mà tiến bước bằng sự tàn nhẫn và quyết liệt.',22,20,2150,'2026-08-07 07:25:21.534753',840,'2025-09-12 00:00:00.000000',1,_binary '','ONGOING',NULL,'Quang Âm Chi Ngoại','https://www.youtube.com/watch?v=RLNi4b_K2Yc','movie-platform/56c116c7-73de-4358-a41e-312e11be396b.webp');
INSERT IGNORE INTO `films` (`id`, `average_rating`, `country`, `description`, `duration_minutes`, `episode_count`, `follow_count`, `last_update`, `rating_count`, `release_date`, `season`, `series`, `status`, `thumbnail_url`, `title`, `trailer_url`, `thumbnail_file_id`) VALUES ('fa040000-0000-0000-0000-000000000004',4.8,'CHINA','Vì đại nghĩa của thiên hạ, Bạch Tiểu Thuần không còn lựa chọn nào khác ngoài quyết chiến với Thông Thiên Đạo Nhân. Khi thế giới cũ sụp đổ, mọi người lưu lạc đến Vĩnh Hằng Đại Lục ngoài Thiên Ngoại. Tại vùng đất mới này, Bạch Tiểu Thuần sẽ phải đối mặt với những thử thách khắc nghiệt chưa từng có cùng những cường địch hùng mạnh hơn bao giờ hết…',20,40,3900,'2026-08-07 07:35:59.851961',1300,'2025-01-10 00:00:00.000000',4,_binary '','ONGOING',NULL,'Nhất Niệm Vĩnh Hằng Phần Cuối','https://www.youtube.com/watch?v=jziW3kjEKTA','movie-platform/335484f5-3d2a-41be-b773-1056eafafe69.webp');
INSERT IGNORE INTO `films` (`id`, `average_rating`, `country`, `description`, `duration_minutes`, `episode_count`, `follow_count`, `last_update`, `rating_count`, `release_date`, `season`, `series`, `status`, `thumbnail_url`, `title`, `trailer_url`, `thumbnail_file_id`) VALUES ('fa050000-0000-0000-0000-000000000005',4.5,'CHINA','Chiêm ngưỡng phàm nhân mưu trí Hàn Lập làm thế nào vững vàng đạo tâm, từng bước mưu tính, khắc chế ma đạo, cướp đoạt chí bảo, tung hoành tinh hải, hảo hận khoái ý, trở thành cường giả bá chủ tam giới.\nMai sau tiên giới trùng phùng, một tiếng “đạo hữu” thấm tựa khói sương trần thế.',20,35,2600,'2026-08-07 07:21:17.093234',780,'2025-06-01 00:00:00.000000',3,_binary '','ONGOING',NULL,'Phàm Nhân Tu Tiên Phần 3','https://www.youtube.com/watch?v=h37Z8jGRZK8','movie-platform/680df033-f44f-4865-ad59-98a2d807f834.webp');
INSERT IGNORE INTO `films` (`id`, `average_rating`, `country`, `description`, `duration_minutes`, `episode_count`, `follow_count`, `last_update`, `rating_count`, `release_date`, `season`, `series`, `status`, `thumbnail_url`, `title`, `trailer_url`, `thumbnail_file_id`) VALUES ('fa060000-0000-0000-0000-000000000006',4.4,'CHINA','Một chàng trai thành đạt được bạn bè yêu quý. Trong một lần họp mặt cùng nhóm bạn, một sự cố huyền ảo đã xảy ra và đưa cả nhóm bạn quay trở về thời cổ đại, thời kỳ tồn tại của những vị thần. Nơi đó, mọi mâu thuẫn chỉ có thể giải quyết bằng sức mạnh…Có tồn tại thế giới thần tiên này ư? Có phải đây chỉ là những truyền thuyết hay sự tích ? Những gì nhìn thấy là sự thật hay là ảo mộng.\n\nPhim được chuyển thể từ tiểu thuyết “Già Thiên” của tác giả Thần Đông (Thế Giới Hoàn Mỹ) và cùng studio với Phàm Nhân Tu Tiên\nMain: Diệp Phàm\n\nThê tử: Cơ Tử Nguyệt\nHồng nhan: Tần Dao, An Diệu Y',20,40,1980,'2026-08-07 07:20:54.192904',690,'2025-04-15 00:00:00.000000',1,_binary '','ONGOING',NULL,'Già Thiên','https://www.youtube.com/watch?v=rew4Db8RHos','movie-platform/4bb7f398-8f00-4a19-bb1e-ab19a6b9211b.png');
INSERT IGNORE INTO `films` (`id`, `average_rating`, `country`, `description`, `duration_minutes`, `episode_count`, `follow_count`, `last_update`, `rating_count`, `release_date`, `season`, `series`, `status`, `thumbnail_url`, `title`, `trailer_url`, `thumbnail_file_id`) VALUES ('fa070000-0000-0000-0000-000000000007',4.4,'CHINA','Từ nhỏ, Cốc An luôn nỗ lực tu luyện với khát vọng trở thành tiên nhân. Thế nhưng, vì trời sinh thiếu linh căn nên anh vô duyên với tiên đạo, lại còn bị lừa vào một khu lừa đảo của giới tu tiên, nhiều lần cận kề cái chết.\n\nSau khi trải qua vô vàn đau khổ và bị dồn đến đường cùng, Cốc An quyết tâm vùng lên báo thù, từng bước nghịch thiên cải mệnh. Con đường thượng vị của anh bắt đầu từ đây, với lời thề một ngày sẽ một đao chém rách cả thương khung.',20,15,1350,'2026-08-07 07:20:13.954461',420,'2026-01-20 00:00:00.000000',1,_binary '','ONGOING',NULL,'Nhất Trảm Thương Khung','https://www.youtube.com/watch?v=XCUOTmU-014','movie-platform/6514f526-9b16-4bcc-8ab1-7083fa01477d.webp');
INSERT IGNORE INTO `films` (`id`, `average_rating`, `country`, `description`, `duration_minutes`, `episode_count`, `follow_count`, `last_update`, `rating_count`, `release_date`, `season`, `series`, `status`, `thumbnail_url`, `title`, `trailer_url`, `thumbnail_file_id`) VALUES ('fb010000-0000-0000-0000-000000000001',4.8,'KOREA','Phim \"Đặc Vụ Kim Tái Khởi Động\" xoay quanh câu chuyện về một ông bố yêu thương con hết mực, người từng là một lính đặc nhiệm với những kĩ năng sắc bén. Với tên gốc \"Agent Kim Reactivated\" và sự chỉ đạo của đạo diễn 이승영, bộ phim này hứa hẹn sẽ mang đến cho khán giả những tràng cười, những pha hành động mãn nhãn và cả những giây phút hồi hộp đến nghẹt thở. Trong phim, diễn viên 소지섭 vào vai Kim, một quản lý phải đối mặt với thử thách lớn lao khi con gái của mình bị đe dọa. Để bảo vệ người thân, Kim buộc phải đánh thức những kĩ năng và bản lĩnh đã từng giúp anh trở thành một đặc vụ điêu luyện. Cuộc hành trình của Kim không chỉ là để cứu con mình mà còn là cuộc trả thù không khoan nhượng với những kẻ xâm phạm đến hạnh phúc gia đình anh. Dàn diễn viên tham gia bao gồm các tên tuổi nổi tiếng như 최대훈, 윤경호, 주상욱, 손나은, Lee Dong-ha, 조복래, 김성규, 원현준 và 원태민. Sự hội tụ của những diễn viên tài năng cùng với kịch bản hấp dẫn về hành động, hình sự, phiêu lưu và chính kịch hứa hẹn sẽ mang đến cho khán giả những trải nghiệm điện ảnh độc đáo và khó quên. \"Đặc Vụ Kim Tái Khởi Động\" không chỉ là một bộ phim hành động thú vị mà còn là một tác phẩm nghệ thuật kể về tình yêu và sự hy sinh của một ông bố. Để cảm nhận đầy đủ cảm xúc và tiếng cười, hãy cùng Motchill xem ngay bộ phim này để trải nghiệm những phút giây căng thẳng và đầy kịch tính.',60,10,891,'2026-08-07 09:50:19.024146',310,'2026-01-15 00:00:00.000000',1,_binary '','COMPLETED',NULL,'Đặc Vụ Kim Tái Khởi Động','https://www.youtube.com/watch?v=k5IDEniQNEk','movie-platform/00de4f21-6501-4e2a-bb96-bb2ba7e3df16.webp');
INSERT IGNORE INTO `films` (`id`, `average_rating`, `country`, `description`, `duration_minutes`, `episode_count`, `follow_count`, `last_update`, `rating_count`, `release_date`, `season`, `series`, `status`, `thumbnail_url`, `title`, `trailer_url`, `thumbnail_file_id`) VALUES ('fb020000-0000-0000-0000-000000000002',4.6,'KOREA','Trong bối cảnh một xã hội chủ nghĩa quân chủ lập hiến ở thế kỷ 21, bộ phim \"Phu Nhân Đại Quân Thế Kỷ 21\" (tên gốc: Perfect Crown) mang đến cho khán giả một câu chuyện đầy cảm hứng về tình yêu vượt qua ranh giới địa vị xã hội. Được đạo diễn bởi 박준화 và 배희영, bộ phim quy tụ dàn diễn viên tài năng với sự góp mặt của IU, 변우석, 노상현, 공승연, 유수빈, 이재원, 채서안, Cho Seung-yeon, 박지예, và 성준. Câu chuyện bắt đầu khi một người phụ nữ trẻ, sở hữu tất cả những gì mà mọi người khao khát, gặp gỡ một vị hoàng tử trong hoàng tộc. Mặc dù hoàng tử thuộc dòng dõi hoàng tộc, anh ta lại cảm thấy bất lực trước những trách nhiệm và áp lực xã hội. Sự gặp gỡ này đã mở ra một cánh cửa mới cho họ, khi tình yêu đẩy họ vượt qua những rào cản của địa vị xã hội và học cách yêu thương và hiểu nhau hơn. \"Phu Nhân Đại Quân Thế Kỷ 21\" không chỉ là một bộ phim tình yêu lãng mạn mà còn là một tác phẩm mang đậm yếu tố hài hước và chính kịch. Với câu chuyện cảm động, những pha diễn xuất tinh tế từ các diễn viên hàng đầu Hàn Quốc, bộ phim hứa hẹn mang đến cho khán giả những trải nghiệm đầy xúc cảm và ý nghĩa. Nếu bạn đam mê những bộ phim kết hợp giữa hài hước và chính kịch, \"Phu Nhân Đại Quân Thế Kỷ 21\" là sự lựa chọn lý tưởng. Hãy cùng MotPhim khám phá câu chuyện đẹp này và tận hưởng những khoảnh khắc đầy cảm xúc mà bộ phim mang lại. Xem ngay để hiểu rõ hơn về tình yêu và sự đan xen giữa các tầng lớp xã hội trong thế giới đầy màu sắc của \"Phu Nhân Đại Quân Thế Kỷ 21\".',65,16,620,'2026-08-07 10:28:37.461088',195,'2026-03-01 00:00:00.000000',1,_binary '','COMPLETED',NULL,'Phu Nhân Đại Quân Thế Kỷ 21','https://www.youtube.com/watch?v=AGh-CwbKMlM','movie-platform/3c5400c7-6cea-4661-a561-ada99462e617.webp');
INSERT IGNORE INTO `films` (`id`, `average_rating`, `country`, `description`, `duration_minutes`, `episode_count`, `follow_count`, `last_update`, `rating_count`, `release_date`, `season`, `series`, `status`, `thumbnail_url`, `title`, `trailer_url`, `thumbnail_file_id`) VALUES ('fb030000-0000-0000-0000-000000000003',4.7,'KOREA','\"Tiếng yêu này anh dịch được không?\" là một bộ phim hấp dẫn xoay quanh cuộc hành trình đi khắp thế giới của một người nổi tiếng để quay chương trình truyền hình. Câu chuyện tập trung vào mối quan hệ giữa người nổi tiếng đó và phiên dịch viên - người có nhiệm vụ chuyển ngữ cho cô. Tuy nhiên, tình yêu giữa họ gặp khó khăn khi ngôn ngữ không thể nào hiểu được. Điểm đặc biệt của bộ phim này chính là cách thể hiện sự giao tiếp và hiểu biết giữa hai nhân vật chính thông qua ngôn ngữ của tình yêu. Khán giả sẽ được chứng kiến những tình tiết hài hước nhưng không kém phần xúc động khi họ cố gắng hiểu và chia sẻ cảm xúc với nhau bằng những cách khác nhau. Với sự tham gia của dàn diễn viên tài năng như 김선호, 고윤정, 福士蒼汰, 이이담, 최우성, 김원해, bộ phim hứa hẹn mang đến những màn trình diễn đầy sức hút và cuốn hút người xem từ màn hình nhỏ. Mỗi diễn viên đều đã thể hiện tài năng diễn xuất của mình qua từng cử chỉ, ngôn ngữ cơ thể và diễn xuất tình cảm, tạo nên một bức tranh hoàn hảo về tình yêu và sự hiểu biết. \"Tiếng yêu này anh dịch được không?\" không chỉ là câu chuyện về tình yêu mà còn là hành trình tìm kiếm ngôn ngữ riêng của mỗi con người, từ những biểu cảm đơn giản cho đến những dòng thông điệp sâu xa, qua đó thách thức khán giả suy nghĩ về ý nghĩa thực sự của tình yêu và sự hiểu biết. Với sự kết hợp hài hước và chính kịch, bộ phim hứa hẹn đem đến những phút giây giải trí thú vị và ý nghĩa cho khán giả. Qua \"Tiếng yêu này anh dịch được không?\", khán giả sẽ được đắm chìm trong không gian nghệ thuật đầy màu sắc của tình yêu và hiểu biết, đồng thời nhận ra rằng, dù có bao nhiêu khó khăn về ngôn ngữ, tình yêu vẫn là ngôn ngữ chung của tất cả mọi người. Hãy cùng theo dõi và khám phá tác phẩm điện ảnh đặc sắc này trên Motchilltv để trải nghiệm những cảm xúc đặc biệt và hấp dẫn nhất!',55,12,1200,'2026-08-07 07:40:44.837086',450,'2026-02-14 00:00:00.000000',1,_binary '','COMPLETED',NULL,'Tiếng yêu này anh dịch được không?','https://www.youtube.com/watch?v=tNZG1aLBATY','movie-platform/9e182526-da30-4cfc-bab9-17eec2b4322b.webp');
INSERT IGNORE INTO `films` (`id`, `average_rating`, `country`, `description`, `duration_minutes`, `episode_count`, `follow_count`, `last_update`, `rating_count`, `release_date`, `season`, `series`, `status`, `thumbnail_url`, `title`, `trailer_url`, `thumbnail_file_id`) VALUES ('fb040000-0000-0000-0000-000000000004',4.9,'USA','Euphoria mùa 3 - lấy mốc thời gian nhảy cóc 5 năm sau các sự kiện ở trường trung học. Nội dung xoay quanh hành trình trưởng thành và đối mặt với thực tế phũ phàng của Rue Bennett khi cô vật lộn với việc cai nghiện, tìm kiếm đức tin và vướng vào các hoạt động buôn bán ma túy phi pháp tại California.',58,10,2100,'2026-08-07 09:31:22.651763',880,'2026-04-05 00:00:00.000000',3,_binary '','COMPLETED',NULL,'Euphoria Season 3','https://www.youtube.com/watch?v=mn94zN20h3s','movie-platform/29d627b8-5f49-41dd-8d50-b77c4c45e207.jpg');
INSERT IGNORE INTO `films` (`id`, `average_rating`, `country`, `description`, `duration_minutes`, `episode_count`, `follow_count`, `last_update`, `rating_count`, `release_date`, `season`, `series`, `status`, `thumbnail_url`, `title`, `trailer_url`, `thumbnail_file_id`) VALUES ('fb050000-0000-0000-0000-000000000005',4.8,'USA','Phim \"Andor Phần 2\" (tựa gốc: Andor Season 2, 2023) là phần tiếp theo của series phim tiền truyện nằm trong vũ trụ Star Wars, tập trung vào hành trình của nhân vật Cassian Andor. Bối cảnh của bộ phim đặt trong một thế giới đầy rẫy nguy hiểm, lừa dối và âm mưu, nơi mà Cassian Andor phải đối mặt với những thử thách cam go để trở thành một anh hùng của phe nổi dậy. Được sản xuất tại Mỹ, \"Andor Phần 2\" hứa hẹn mang đến cho khán giả những đoạn phim kịch tính, với sự phát triển sâu sắc về tâm lý nhân vật. Đạo diễn và biên kịch của phim đã tập trung vào việc xây dựng một câu chuyện hấp dẫn, đầy cảm xúc và nhiều bất ngờ. Trong phần này, khán giả sẽ được chứng kiến sự trở lại của dàn diễn viên tài năng như Diego Luna trong vai Cassian, Kyle Soller, Stellan Skarsgård, Denise Gough, Adria Arjona, Genevieve O\'Reilly, Faye Marsay, Anton Lesser, Elizabeth Dulau, và Varada Sethu. Sự hội tụ của những tên tuổi đình đám này hứa hẹn đem lại những pha hành động mãn nhãn, những tình tiết kịch tính và những màn trình diễn đầy ấn tượng. \"Andor Phần 2\" tiếp tục khai thác và khám phá những góc khuất của vũ trụ Star Wars, đưa người xem vào cuộc phiêu lưu hấp dẫn, đầy màu sắc và sâu lắng. Với thời lượng khoảng 40 phút mỗi tập, phim thu hút đối tượng khán giả yêu thích thể loại khoa học viễn tưởng, hành động và phiêu lưu. \"Andor Phần 2\" mang đến cái nhìn mới mẻ và độc đáo về thế giới của Star Wars, với những tình tiết đầy kịch tính và những yếu tố chính kịch sẽ khiến khán giả không thể rời mắt khỏi màn hình.',50,12,1540,'2026-08-07 09:30:26.247248',620,'2026-05-10 00:00:00.000000',2,_binary '','COMPLETED',NULL,'Andor Season 2','https://www.youtube.com/watch?v=QHAu5XHsDhQ','movie-platform/b6c6ac11-9023-4869-b883-d7d2f245b388.jpg');
INSERT IGNORE INTO `films` (`id`, `average_rating`, `country`, `description`, `duration_minutes`, `episode_count`, `follow_count`, `last_update`, `rating_count`, `release_date`, `season`, `series`, `status`, `thumbnail_url`, `title`, `trailer_url`, `thumbnail_file_id`) VALUES ('fb060000-0000-0000-0000-000000000006',4.9,'CHINA','Thiếu nữ Ngụy Anh Lạc (Ngô Cẩn Ngôn) quyết tâm vào cung để tìm hung thủ sát hại tỷ tỷ. Cô nhầm tưởng rằng đệ đệ của Hoàng đế - Phó Hằng (Hứa Khải) là hung thủ thật sự nên đã giả vờ tiếp cận y. Phú Sát hoàng hậu (Tần Lam) thấy Anh Lạc thông minh nên đã giữ cô lại bên mình, hết lòng chăm sóc dạy bảo. Các nữ nhân trong cung vì Hoàng đế Càn Long (Nhiếp Viễn) mà không ngần ngại bày đủ mưu kế. Ngụy Anh Lạc buộc phải không ngừng chiến đấu để bảo vệ bản thân mình.',45,70,3400,'2026-08-07 07:42:02.951149',1500,'2026-01-01 00:00:00.000000',1,_binary '','COMPLETED',NULL,'Diên Hy Công Lược','https://www.youtube.com/watch?v=Ej8ldNc9i9Q','movie-platform/da826ecf-7dde-4756-9317-edc455976ece.webp');
INSERT IGNORE INTO `films` (`id`, `average_rating`, `country`, `description`, `duration_minutes`, `episode_count`, `follow_count`, `last_update`, `rating_count`, `release_date`, `season`, `series`, `status`, `thumbnail_url`, `title`, `trailer_url`, `thumbnail_file_id`) VALUES ('fb070000-0000-0000-0000-000000000007',4.6,'CHINA','\"Tiêu Dao\" là một bộ phim viễn tưởng, khoa học, chính kịch nổi tiếng, đầy kịch tính và mê hoặc khán giả từ khắp nơi trên thế giới. Bối cảnh của câu chuyện là thế giới đầy ma mị và bí ẩn, nơi mà nhân tộc và yêu tộc đều đang tìm kiếm Thần Tuyền Ngọc Lễ - viên ngọc quý giá có khả năng thần bí. Tiêu Dao, nhân vật chính trong phim, là một cô gái mạnh mẽ, phóng khoáng và sở hữu khả năng ứng biến thiên phú nổi bật. Đồng thời, cô cũng là người khơi mở hành trình kỳ ảo xuyên qua Vạn Yêu Cốc - nơi đầy rẫy yêu ma và bí ẩn. Trong chuyến hành trình này, Tiêu Dao đã làm đảo điên cả thế giới yêu ma, mở ra những khám phá đầy thú vị và nguy hiểm. Phim còn xoay quanh nhân vật Hồng Diệp, vua vạn yêu được người dân tôn sùng. Hồng Diệp đã xuất hiện để bảo vệ Vạn Yêu Cốc khỏi sự tranh chấp về Thần Tuyền Ngọc Lễ. Trong quá trình đấu tranh, Hồng Diệp đã dần nhận ra bản chất thực sự của bản thân và của vạn vật xung quanh, từ đó ông hiểu rõ hơn về sự tham lam và dục vọng. Không chỉ vậy, Hồng Diệp còn phát hiện tình cảm đặc biệt với Tiêu Dao - cô gái với linh hồn thuần khiết và không bị dẫn dụ bởi dục vọng. Hai người đã cùng nhau trải qua những thử thách, những vụ án kỳ lạ và đối đầu với những kẻ thù bí ẩn, tạo nên những tình tiết căng thẳng và ly kỳ cho bộ phim \"Tiêu Dao\". Được đạo diễn bởi 徐纪周 và có sự tham gia của các diễn viên tài năng như 谭松韵, 侯明昊, Wang Duo, 黄家婧, 张小婉, Guo Yun Qi, Li Jing, Cui Shaohan, Xie Zecheng, và 劉燁, \"Tiêu Dao\" không chỉ là một bộ phim giải trí đầy lôi cuốn mà còn là một tác phẩm nghệ thuật đầy sức hút và ý nghĩa. Nếu bạn là người yêu thích thể loại phim viễn tưởng, khoa học hấp dẫn hòa quyện với những yếu tố chính kịch sâu sắc, \"Tiêu Dao\" chắc chắn sẽ là lựa chọn tuyệt vời để thưởng thức. Hãy cùng Motchilltv khám phá bộ phim này ngay hôm nay để trải nghiệm những cung bậc cảm xúc độc đáo mà nó mang lại!',45,40,1150,'2026-08-07 07:38:21.762291',510,'2026-02-20 00:00:00.000000',1,_binary '','COMPLETED',NULL,'Tiêu Dao','https://www.youtube.com/watch?v=pE_QQmqWzOg','movie-platform/4d5c011c-628a-4954-907d-f5abeab14723.webp');
INSERT IGNORE INTO `films` (`id`, `average_rating`, `country`, `description`, `duration_minutes`, `episode_count`, `follow_count`, `last_update`, `rating_count`, `release_date`, `season`, `series`, `status`, `thumbnail_url`, `title`, `trailer_url`, `thumbnail_file_id`) VALUES ('fb080000-0000-0000-0000-000000000008',4.7,'USA','Thứ Tư Phần 2 (Wednesday Season 2) là phần tiếp theo của series trinh thám mang đậm phong cách kinh dị pha lôi cuốn, do Mỹ sản xuất, chính thức ra mắt vào cuối năm 2025. Trở lại Nevermore Academy, Wednesday Addams với nét lạnh lùng nhưng không kém phần thông minh. Tiếp tục đẩy mạnh hành trình khai phá những bí ẩn siêu nhiên quanh mình, trong khi vẫn giữ vững phong thái cá nhân sắc bén và đậm tính \"Gothic\" đặc trưng.\n\nĐiểm nhấn mạnh mẽ của Wednesday Season 2 là sự xuất hiện của gia đình Addams từ Morticia, Gomez đến Pugsley. Trực tiếp bước vào trung tâm các biến động tại Nevermore. Bối cảnh được chuyển sang Ireland, mang lại không gian ám ảnh và sang trọng, bổ sung thêm chiều sâu hình ảnh cho loạt cảnh rùng rợn và ẩn chứa bí mật.\n\nPhim mở đầu bằng loạt hiện tượng siêu hình: Wednesday nhìn thấy cảnh Enid bạn thân sóng đôi có thể sẽ chết và cô sẽ làm mọi cách, kể cả đánh đổi chính mình, để ngăn điều đó xảy ra. Không khí trở nên căng thẳng với những thế lực bóng tối như \"LOIS experiment\", Avian Killer kẻ sát nhân bí ẩn và nhân vật Hyde (Tyler) quay lại với dáng vẻ đáng sợ.\n\nVới sự dẫn dắt của Jenna Ortega đầy cuốn hút, tài năng kể chuyện của Tim Burton qua phong cách stop-motion và diễn xuất đậm cá tính, Wednesday Season 2 tiếp tục là hành trình lôi cuốn, âm u, nhưng không kém phần hài hước. Đã khiến người xem sẵn sàng ngồi lại khám phá đến tập cuối.',60,8,2400,'2026-08-07 09:32:15.533119',980,'2026-08-06 00:00:00.000000',2,_binary '','COMPLETED',NULL,'Wednesday Season 2','https://www.youtube.com/watch?v=03u4xyj0TH4','movie-platform/a92a2b81-2e9b-4af4-b286-b53608f4699d.jpg');
INSERT IGNORE INTO `films` (`id`, `average_rating`, `country`, `description`, `duration_minutes`, `episode_count`, `follow_count`, `last_update`, `rating_count`, `release_date`, `season`, `series`, `status`, `thumbnail_url`, `title`, `trailer_url`, `thumbnail_file_id`) VALUES ('fs010000-0000-0000-0000-000000000001',4.9,'USA','Không còn Tony Stark, MJ hay Ned kề cận, Peter buộc phải đơn thân độc mã đối diện với phe đối đầu bí ẩn. Tuy nhiên, khi áp lực ngày càng gia tăng, nó kích hoạt một sự biến đổi thể chất bất ngờ, đe dọa chính sự tồn tại của anh. Đồng thời, một chuỗi tội phạm bí ẩn mới xuất hiện, kéo theo một trong những mối đe dọa mạnh mẽ nhất mà Spider-Man từng đối mặt',135,0,4500,'2026-08-07 09:29:32.905019',2100,'2026-07-04 00:00:00.000000',1,_binary '\0','COMPLETED',NULL,'Spider-Man: Brand New Day','https://www.youtube.com/watch?v=62bIsvRcPv0','movie-platform/3a2adc39-73a4-4043-93d5-3c281ce56dbd.jpg');
INSERT IGNORE INTO `films` (`id`, `average_rating`, `country`, `description`, `duration_minutes`, `episode_count`, `follow_count`, `last_update`, `rating_count`, `release_date`, `season`, `series`, `status`, `thumbnail_url`, `title`, `trailer_url`, `thumbnail_file_id`) VALUES ('fs020000-0000-0000-0000-000000000002',4.9,'CHINA','Sau kiếp nạn, mặc dù linh hồn của Na Tra và Ngao Bính được bảo toàn, nhưng thân xác của họ sẽ sớm bị hủy hoại hoàn toàn. Thái Ất Chân Nhân dự định sử dụng Bảy Đóa Sen Sắc Màu để tái tạo thân xác cho họ. Tuy nhiên, trong quá trình tái tạo, họ đã gặp phải vô vàn khó khăn. Số phận của Na Tra và Ngao Bính sẽ đi về đâu?',144,0,6800,'2026-08-07 07:47:06.183323',3200,'2026-01-29 00:00:00.000000',2,_binary '\0','COMPLETED',NULL,'Na Tra 2: Ma Đồng Náo Hải','https://www.youtube.com/watch?v=q8ykuxqDsew','movie-platform/2f4c7928-17a9-4c46-9cd1-5f19726ab009.webp');
INSERT IGNORE INTO `films` (`id`, `average_rating`, `country`, `description`, `duration_minutes`, `episode_count`, `follow_count`, `last_update`, `rating_count`, `release_date`, `season`, `series`, `status`, `thumbnail_url`, `title`, `trailer_url`, `thumbnail_file_id`) VALUES ('fs030000-0000-0000-0000-000000000003',4.8,'USA','Bộ phim \"Michael\" là một bức chân dung sống động về cuộc đời và tài năng của một nghệ sĩ có ảnh hưởng to lớn tới thế giới - Michael Jackson. Tác phẩm này không chỉ đề cập đến sự nghiệp âm nhạc đầy thành công mà còn chạm tới những khía cạnh cá nhân và tâm hồn sâu kỹ của ngôi sao này. Sinh ra và lớn lên trong gia đình nghệ sĩ, Michael Jackson từ nhỏ đã tỏ ra có tài năng phi thường và được biết đến qua vai trò giọng ca chính của nhóm nhạc nổi tiếng Jackson Five. Qua những bước chuyển mình trong sự nghiệp âm nhạc, từ thời kỳ nhóm nhạc đến khi trở thành một nghệ sĩ solo có tầm ảnh hưởng to lớn, Michael không ngừng chứng minh bản lĩnh và khao khát sáng tạo không ngừng. Đạo diễn Antoine Fuqua đã thể hiện một cách tinh tế hành trình phấn đấu và tìm kiếm của Michael Jackson thông qua phim \"Michael\". Dàn diễn viên được chọn lựa kỹ lưỡng như Jaafar Jackson, Colman Domingo, Nia Long, Juliano Krue Valdi, KeiLyn Durrel Jones, Miles Teller, Kendrick Sampson, Joseph David-Jones, Jamal Henderson và Rhyan Hill đã tạo nên những khung hình sống động cho nhân vật và câu chuyện. \"Michael\" không chỉ là cái nhìn rõ nét hơn về hào quang sân khấu mà còn là cơ hội để khán giả hiểu rõ hơn về con người Michael Jackson. Bộ phim giúp khán giả đắm chìm trong không gian thời gian, từ những kỉ niệm ngọt ngào trong tuổi thơ đến những áp lực và trắc trở trong sự nghiệp người nghệ sĩ vĩ đại này. Với \"Michael\", Motchill đã mang đến cho người xem một cơ hội hiếm hoi được đắm chìm trong thế giới đầy màu sắc và âm nhạc của ngôi sao Michael Jackson. Hãy cùng Motchilltv tận hưởng bộ phim này và khám phá thêm về một trong những huyền thoại âm nhạc thế giới.',148,0,3100,'2026-08-07 07:40:03.633066',1400,'2026-04-18 00:00:00.000000',1,_binary '\0','COMPLETED',NULL,'Michael','https://www.youtube.com/watch?v=3zOLzsbOleM','movie-platform/e4617095-0d77-488e-b94c-f24a53dac473.webp');
INSERT IGNORE INTO `films` (`id`, `average_rating`, `country`, `description`, `duration_minutes`, `episode_count`, `follow_count`, `last_update`, `rating_count`, `release_date`, `season`, `series`, `status`, `thumbnail_url`, `title`, `trailer_url`, `thumbnail_file_id`) VALUES ('fs040000-0000-0000-0000-000000000004',4.9,'USA','Ra đời cách đây hơn 3.000 năm, The Odyssey là một trong những tác phẩm đặt nền móng cho văn học phương Tây. Đến nay, sử thi được Christopher Nolan - từng theo học và lấy bằng cử nhân Văn học Anh trước khi làm phim - chuyển thể thành dự án điện ảnh tham vọng nhất sự nghiệp. Tuy nhiên, thay vì kể lại chiến công của người Hy Lạp, đạo diễn biến cuộc hồi hương của Odysseus thành hành trình đối diện vết thương chiến tranh với những đại cảnh hoành tráng và cách khai thác chiều sâu tâm lý nhân vật.',165,0,4200,'2026-08-07 07:26:17.511265',1850,'2026-06-15 00:00:00.000000',1,_binary '\0','COMPLETED',NULL,'The Odyssey','https://www.youtube.com/watch?v=Mzw2ttJD2qQ','movie-platform/5a45f39a-dafb-4b84-b8ea-0c82f2336cd4.jpg');
INSERT IGNORE INTO `films` (`id`, `average_rating`, `country`, `description`, `duration_minutes`, `episode_count`, `follow_count`, `last_update`, `rating_count`, `release_date`, `season`, `series`, `status`, `thumbnail_url`, `title`, `trailer_url`, `thumbnail_file_id`) VALUES ('fs050000-0000-0000-0000-000000000005',4.8,'USA','Trên hành tinh Pandora huyền bí, nơi mà cuộc sống và thiên nhiên cộng sinh tạo nên một thế giới đẹp mê hồn, câu chuyện trong bộ phim \"Avatar 3: Lửa và Tro Tàn\" tiếp tục khám phá và thách thức sự mạnh mẽ của tình yêu, tính hiệp sĩ và lòng can đảm trong bối cảnh đầy kịch tính và đau thương. Sau những trận chiến đẫm máu với RDA và cái chết đau lòng của đứa con trai yêu quý, nhân vật chính Jake Sully và Neytiri đối mặt với một mối đe dọa mới đến từ tộc Tro Tàn trên Pandora. Tộc Tro Tàn, dưới sự lãnh đạo tàn ác của Varang, đang gieo rắc nỗi kinh hoàng và khủng khiếp khắp nơi. Gia đình Jake phải đứng lên chống lại thế lực đen tối này, không chỉ để bảo vệ Pandora mà còn để bảo vệ những người dân yêu quý trên hành tinh xanh biếc này. Cuộc chiến không chỉ là về sức mạnh vũ trụ mà còn là về lòng can đảm, lòng hy sinh và lòng kiên trì. Jake Sully, một người ngoại đạo nhưng đã trở thành một chiến binh mạnh mẽ của tộc Na\'vi, cùng với Neytiri, người phụ nữ mạnh mẽ và kiên cường, họ cùng nhau đối mặt với những thử thách khó khăn nhất từ trước đến nay. Sự xuất hiện của Varang đe doạ tới cả cuộc sống và quyền lợi của tất cả mọi người trên Pandora, và chỉ có bằng lòng quyết tâm và đoàn kết, họ mới có thể vượt qua khủng hoảng này. Đạo diễn tài ba James Cameron đã mang đến cho khán giả một câu chuyện đầy cảm xúc, đậm chất nhân văn và ý nghĩa sâu sắc. Với dàn diễn viên tài năng như Sam Worthington, Zoe Saldaña, Sigourney Weaver, Stephen Lang, Kate Winslet, Cliff Curtis, Oona Chaplin, Jack Champion, Britain Dalton, và Trinity Bliss, bộ phim \"Avatar 3: Lửa và Tro Tàn\" không chỉ là một tác phẩm giải trí hấp dẫn mà còn là một thông điệp về lòng dũng cảm và tình yêu thương. Viễn tưởng, phiêu lưu và khoa học, \"Avatar 3: Lửa và Tro Tàn\" thực sự là một tác phẩm nghệ thuật đỉnh cao, nơi mà khán giả có thể tìm thấy cảm xúc mạnh mẽ, những bài học ý nghĩa và những giây phút giải trí đầy sức hút.',162,0,5900,'2026-08-07 07:45:02.987429',2900,'2025-12-19 00:00:00.000000',1,_binary '\0','COMPLETED',NULL,'Avatar 3: Lửa và Tro Tàn','https://www.youtube.com/watch?v=nb_fFj_0rq8','movie-platform/c2c85456-7555-47bc-a60c-8399fb652ed6.webp');
INSERT IGNORE INTO `films` (`id`, `average_rating`, `country`, `description`, `duration_minutes`, `episode_count`, `follow_count`, `last_update`, `rating_count`, `release_date`, `season`, `series`, `status`, `thumbnail_url`, `title`, `trailer_url`, `thumbnail_file_id`) VALUES ('fs060000-0000-0000-0000-000000000006',4.6,'VIETNAM','Thỏ Ơi!! Với tâm thế luôn mang đến những điều mới để cho khán giả của mình không nhàm chán, Thỏ Ơi!! - bộ phim điện ảnh thứ 4 của đạo diễn Trấn Thành hứa hẹn sẽ mang đến một màu sắc hoàn toàn khác biệt.',110,0,2300,'2026-08-07 07:39:18.660239',950,'2026-02-17 00:00:00.000000',1,_binary '\0','COMPLETED',NULL,'Thỏ Ơi!','https://www.youtube.com/watch?v=XMv1Zhj5TQg','movie-platform/ff3b83a0-fd3f-48c7-a7e3-dfc8c739b6ad.jpg');
INSERT IGNORE INTO `films` (`id`, `average_rating`, `country`, `description`, `duration_minutes`, `episode_count`, `follow_count`, `last_update`, `rating_count`, `release_date`, `season`, `series`, `status`, `thumbnail_url`, `title`, `trailer_url`, `thumbnail_file_id`) VALUES ('fs070000-0000-0000-0000-000000000007',4.9,'VIETNAM','Mưa Đỏ (Red Rain, 2025) là một trong những bộ phim thuộc thể loại Chính Kịch, Lịch Sử, Chiến Tranh, được sản xuất tại Việt Nam. Câu chuyện kể về “Mưa Đỏ” - Phim truyện điện ảnh về đề tài chiến tranh cách mạng, kịch bản của nhà văn Chu Lai, lấy cảm hứng và hư cấu từ sự kiện 81 ngày đêm chiến đấu anh dũng, kiên cường của nhân dân và cán bộ, chiến sĩ bảo vệ Thành Cổ Quảng Trị năm 1972. Tiểu đội 1 gồm toàn những thanh niên trẻ tuổi và đầy nhiệt huyết là một trong những đơn vị chiến đấu, bám trụ tại trận địa khốc liệt này. Bộ phim là khúc tráng ca bằng hình ảnh, là nén tâm nhang tri ân và tưởng nhớ những người con đã dâng hiến tuổi thanh xuân cho đất nước, mang âm hưởng của tình yêu, tình đồng đội thiêng liêng, là khát vọng hòa bình, hoà hợp dân tộc của nhân dân Việt Nam.Phim có sự góp mặt của các diễn viên nổi tiếng như Đỗ Nhật Hoàng, Steven Nguyễn, Phương Nam. Với diễn xuất ấn tượng cùng cốt truyện hấp dẫn, bộ phim hứa hẹn sẽ mang đến trải nghiệm điện ảnh tuyệt vời cho khán giả. Bộ phim kéo dài trong khoảng 124 phút, sản xuất vào năm 2025 và hiện tại đang ở trạng thái FULL. Không chỉ giải trí, Mưa Đỏ còn truyền tải những thông điệp sâu sắc về cuộc sống, tình cảm và con người.',120,0,3800,'2026-08-07 07:46:20.356605',1600,'2025-09-02 00:00:00.000000',1,_binary '\0','COMPLETED',NULL,'Mưa Đỏ','https://www.youtube.com/watch?v=BD6PoZJdt_M','movie-platform/3a1c161f-1a00-4bb9-8211-934f1a130b2e.webp');
INSERT IGNORE INTO `films` (`id`, `average_rating`, `country`, `description`, `duration_minutes`, `episode_count`, `follow_count`, `last_update`, `rating_count`, `release_date`, `season`, `series`, `status`, `thumbnail_url`, `title`, `trailer_url`, `thumbnail_file_id`) VALUES ('fs080000-0000-0000-0000-000000000008',4.8,'USA','Bộ phim chuyển thể từ sân khấu Broadway thành công nhất mọi thời đại, hiện tượng điện ảnh toàn cầu năm 2024 nay chính thức đi đến hồi kết hoành tráng, kịch tính và đầy cảm xúc trong Wicked: Phần 2. Chương cuối của câu chuyện bắt đầu khi Elphaba và Glinda đã xa cách, mỗi người đang sống với hậu quả từ những lựa chọn của riêng mình. Elphaba giờ đây bị cả xứ Oz xem như Phù thủy độc ác phương Tây, trong khi đó Glinda đã trở thành biểu tượng quyến rũ của Lòng tốt đối với toàn bộ xứ Oz. Và mọi thứ thay đổi khi một cô gái đến từ Kansas bất ngờ xuất hiện, khiến cuộc sống của xứ Oz bị đảo lộn. Glinda và Elphaba buộc phải cùng nhau đối mặt lần cuối, họ phải thật sự thấu hiểu nhau, bằng sự trung thực và đồng cảm, nếu muốn thay đổi chính mình và cả vận mệnh của xứ Oz. Liệu Elphaba và Glinda có thể vượt qua số phận đã được định sẵn để viết lại tương lai cho xứ sở phép màu này?',137,0,2600,'2026-08-07 10:27:45.441449',1200,'2026-01-30 00:00:00.000000',1,_binary '\0','COMPLETED',NULL,'Wicked: For Good','https://www.youtube.com/watch?v=vt98AlBDI9Y&t=20s','movie-platform/329eac15-9998-4adb-948c-322766974814.jpg');
